core-loops-review:
def longest_failure_streak(statuses):
    best = current = 0
    for status in statuses:
        current = current + 1 if status >= 500 else 0
        best = max(best, current)
    return best

core-strings-review:
def parse_header(line):
    name, value = line.split(':', 1)
    return name.strip().lower(), value.strip()

core-functions-review:
def mean_valid(values):
    numbers = [v for v in values if v is not None]
    return sum(numbers) / len(numbers) if numbers else None

core-modules-review:
def expires_on(text, days):
    from datetime import date, timedelta
    return (date.fromisoformat(text) + timedelta(days=days)).isoformat()

core-files-review:
def active_ids(stream):
    import json
    result = []
    for line in stream:
        if line.strip():
            row = json.loads(line)
            if row['active']:
                result.append(row['id'])
    return result

core-debugging-review:
def valid_ports(lines):
    result = []
    for line in lines:
        text = line.strip()
        if text and all('0' <= c <= '9' for c in text):
            port = int(text)
            if 1 <= port <= 65535:
                result.append(port)
    return result
